<script setup>
import {ref,watch,onUnmounted} from 'vue'
const props=defineProps({base:String,runId:String,memory:Object})
const rows=ref([]),error=ref(''),expected=ref({}),notes=ref({}),busy=ref(false),message=ref('')
let sequence=0
async function load(){const id=props.runId,seq=++sequence;rows.value=[];error.value='';message.value='';if(!id)return;try{const r=await fetch(`${props.base}/runs/${id}/memory-application`);if(!r.ok)throw Error('규칙 적용 근거를 불러오지 못했습니다.');const data=await r.json();if(seq===sequence)rows.value=data}catch(e){if(seq===sequence)error.value=e.message}}
watch(()=>props.runId,load,{immediate:true});onUnmounted(()=>{sequence++})
function title(id){return props.memory?.knowledge?.active?.find(r=>r.entry_id===id)?.title || id}
async function label(step){busy.value=true;try{const ids=(expected.value[step]||'').split(/[\s,]+/).filter(Boolean);const r=await fetch(`${props.base}/runs/${props.runId}/applicability-label`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({step_id:step,expected_rule_ids:ids,note:notes.value[step],idempotency_key:crypto.randomUUID()})});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'정답 라벨을 저장하지 못했습니다.');message.value='독립적으로 판단한 적용 대상을 기록했습니다. 규칙을 변경하거나 활성화하지 않습니다.'}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><details class="application-trace"><summary>실행 규칙 선택·이행 근거</summary><p>선택된 규칙과 실제 충족을 구분합니다. 이행 검사는 설정한 구조·입력 대조 범위이며 자유 문장 전체의 정확성 판정이 아닙니다.</p><p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><p v-if="!rows.length">이 Run에는 단계별 규칙 추적이 없습니다. 구현 이전 기록이나 실행 전 상태일 수 있습니다.</p><article v-for="row in rows.filter(r=>r.phase==='SELECT')" :key="row.trace_id"><h4>{{ row.step_id }} · 후보 {{ row.snapshot.candidate_rule_ids.length }} / 선택 {{ row.snapshot.selected_rule_ids.length }}</h4><ul><li v-for="id in row.snapshot.selected_rule_ids" :key="id">{{ title(id) }} <small>{{ id }}</small></li></ul><p v-if="!row.snapshot.selected_rule_ids.length">이 단계에 선택된 정규화 규칙이 없습니다.</p><details v-if="row.snapshot.excluded_reasons.length"><summary>제외 이유</summary><p v-for="(excluded,i) in row.snapshot.excluded_reasons" :key="i">{{ title(excluded.entry_id) }} — {{ excluded.reason }}</p></details><details><summary>실행 제약으로 변환한 내용</summary><pre>{{ JSON.stringify(row.snapshot.compiled_actions,null,2) }}</pre></details><template v-for="checked in rows.filter(r=>r.phase==='VERIFY' && r.step_id===row.step_id)" :key="checked.trace_id"><p><b>{{ checked.snapshot.passed?'설정한 이행 검사 통과':'이행 검사 실패' }}</b></p><ul><li v-for="result in checked.snapshot.results" :key="result.entry_id">{{ title(result.parent_rule_id) }} — {{ result.passed?'충족':'미충족' }}<small v-if="result.semantic_review==='PENDING_HUMAN'">사용자 의미 검토 대기</small><pre>{{ JSON.stringify(result.checks || result.reason,null,2) }}</pre></li></ul></template><p v-if="row.paired_quality_delta">고정 사례 비교에서 관측한 효과: {{ row.paired_quality_delta.paired_case_gains }}개 개선 / {{ row.paired_quality_delta.paired_case_regressions }}개 퇴행. 직전 Run과의 점수차가 아닙니다.</p><p v-else>이 실행의 품질 효과는 동일 입력의 비교 근거가 없거나 아직 집계되지 않아 미확인입니다.</p><details><summary>적용 대상 회수율을 위한 사용자 정답 기록</summary><p>선택 결과와 별개로 이 단계에 필요했던 규칙을 판단하세요. 누락된 규칙도 ID로 적을 수 있습니다. 실제 판단이 없으면 회수율은 자료 없음으로 표시합니다.</p><label>필요했던 규칙 ID · 쉼표로 구분<textarea v-model="expected[row.step_id]" rows="2"></textarea></label><label>판단 근거<textarea v-model="notes[row.step_id]" rows="2"></textarea></label><button class="secondary" @click="label(row.step_id)" :disabled="busy || !notes[row.step_id]?.trim()">내 적용 대상 판단 기록</button></details></article></details></template>
<style scoped>.application-trace{padding:18px;background:#f3f5ed;border-left:3px solid #788d69;margin:16px 0;font-size:12px}.application-trace summary{cursor:pointer;font-weight:600}.application-trace article{padding-block:16px;border-bottom:1px solid #d2dbc8}.application-trace p{line-height:1.8}.application-trace small{display:block;color:#718066;overflow-wrap:anywhere}.application-trace pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:260px;overflow:auto;font:11px/1.6 Consolas,monospace}.application-trace label{display:grid;gap:6px;margin:12px 0}.application-trace textarea{width:100%;padding:8px;font:inherit;border:1px solid #c5d0b9;background:#fff}</style>
